import{_ as r,o as e,c as a,ag as d}from"./chunks/framework.Aev9KvMf.js";const p=JSON.parse('{"title":"儿童青少年生长迟缓食养指南（2023年版）","description":"国家卫健委《儿童青少年生长迟缓食养指南（2023年版）》可执行整理：家长能直接照做的行动清单，每条出处可一键跳回原文对应页。","frontmatter":{"title":"儿童青少年生长迟缓食养指南（2023年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2023年版","published":"2023-01","source_url":"https://www.nhc.gov.cn/wjw/c100378/202301/7faed9993c9b45aea158c5335346f282.shtml","status":"现行","tags":["生长迟缓","儿童","食养","饮食指导","行动清单"],"reviewed":false,"description":"国家卫健委《儿童青少年生长迟缓食养指南（2023年版）》可执行整理：家长能直接照做的行动清单，每条出处可一键跳回原文对应页。"},"headers":[],"relativePath":"guides/growth-retardation-2023.md","filePath":"guides/growth-retardation-2023.md"}'),o={name:"guides/growth-retardation-2023.md"};function h(i,t,g,s,n,l){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="儿童青少年生长迟缓食养指南-2023年版" tabindex="-1">儿童青少年生长迟缓食养指南（2023年版） <a class="header-anchor" href="#儿童青少年生长迟缓食养指南-2023年版" aria-label="Permalink to &quot;儿童青少年生长迟缓食养指南（2023年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据官方 PDF 原文整理，尚未逐条对照原文校验；校验通过前请以原文为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页所有建议均<strong>整理自官方文件原文</strong>，每条&quot;出处&quot;均可点击直达原文对应页；标注【本站提示】的少数条目为中性工具提示，不代表医学建议。本站不构成诊疗建议，与医生的治疗方案冲突时，<strong>以医嘱为准</strong>。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/sps/c100088/202301/f01895a06c5349ef999f25da833c166d/files/1732844467736_68919.pdf" target="_blank" rel="noreferrer">官方全文 PDF（卫健委直链）</a>）· 一级来源。下文&quot;出处&quot;链接指向本站镜像的<a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf" target="_blank" rel="noreferrer">官方原文 PDF</a>（政府公文，属公共领域）。</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>生长迟缓的儿童青少年及其家长，也面向校医、营养指导人员（<a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=3" target="_blank" rel="noreferrer">原文·前言</a>）。<strong>先就医明确原因，再参考食养安排日常膳食。</strong></p><h2 id="速览卡-一屏看完" tabindex="-1">速览卡（一屏看完） <a class="header-anchor" href="#速览卡-一屏看完" aria-label="Permalink to &quot;速览卡（一屏看完）&quot;">​</a></h2><p><strong>六条原则</strong>：食物多样满足生长需要 → 因人因地因时食养、调理脾胃 → 合理烹调、培养健康饮食行为 → 营养教育、健康食物环境 → 适宜身体活动、关注睡眠心理 → 定期监测体格发育。（<a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=6" target="_blank" rel="noreferrer">原文·三</a>）</p><table tabindex="0"><thead><tr><th>关键数字</th><th>数值</th><th>出处</th></tr></thead><tbody><tr><td>进餐结构</td><td>2～5 岁每天 <strong>3 次正餐 + 2 次加餐</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>运动</td><td>2～5 岁每天活动 <strong>3 小时</strong>（户外 ≥2 小时，中高强度累计 ≥1 小时）；6～17 岁每天累计中高强度 <strong>≥1 小时</strong>，每周 <strong>3 天</strong>强化肌肉/骨健康运动</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=10" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>视屏</td><td>2～5 岁 <strong>≤1 小时/日</strong>；6～17 岁 <strong>≤2 小时/日</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=10" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>睡眠</td><td>2～5 岁 <strong>10～13 小时</strong>（含 1～2 小时午睡）；6～12 岁 <strong>9～12 小时</strong>；13～17 岁 <strong>8～10 小时</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=10" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>烹调方式</td><td>宜蒸、煮、炖、煨；少油炸、烧烤、腌渍</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr></tbody></table><h2 id="行动清单" tabindex="-1">行动清单 <a class="header-anchor" href="#行动清单" aria-label="Permalink to &quot;行动清单&quot;">​</a></h2><h3 id="🍚-吃" tabindex="-1">🍚 吃 <a class="header-anchor" href="#🍚-吃" aria-label="Permalink to &quot;🍚 吃&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>食物多样，保证能量和营养素摄入充足；三餐定时定量、饮食规律</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>增加瘦肉、水产品、禽类、蛋类、大豆等富含优质蛋白质的食物</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=7" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>食材切小切碎、质地软烂易消化；合理烹调以蒸煮炖煨为主</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>按中医证型调理脾胃、因人因地因时施膳</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr></tbody></table><h3 id="🏃-动-😴-睡" tabindex="-1">🏃 动 / 😴 睡 <a class="header-anchor" href="#🏃-动-😴-睡" aria-label="Permalink to &quot;🏃 动 / 😴 睡&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>按年龄段保证身体活动与户外活动时长（见速览卡）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=10" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>保证睡眠时长（见速览卡），关注心理健康</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=10" target="_blank" rel="noreferrer">三(五)</a></td></tr></tbody></table><h3 id="🩺-测与就医-👨‍👩‍👧-环境" tabindex="-1">🩺 测与就医 / 👨‍👩‍👧 环境 <a class="header-anchor" href="#🩺-测与就医-👨‍👩‍👧-环境" aria-label="Permalink to &quot;🩺 测与就医 / 👨‍👩‍👧 环境&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>定期监测体格发育，强化膳食评估和指导</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=11" target="_blank" rel="noreferrer">三(六)</a></td></tr><tr><td>开展营养教育，营造健康食物环境（家庭、学校共同参与）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>就医排查过敏、特发性矮小、生长激素缺乏、慢性系统疾病等原因</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=4" target="_blank" rel="noreferrer">二</a></td></tr></tbody></table><h2 id="附录怎么用" tabindex="-1">附录怎么用 <a class="header-anchor" href="#附录怎么用" aria-label="Permalink to &quot;附录怎么用&quot;">​</a></h2><ul><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=13" target="_blank" rel="noreferrer">附录1《食物选择》</a></strong>（含**<a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=14" target="_blank" rel="noreferrer">证型食药物质推荐</a>**）· <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=14" target="_blank" rel="noreferrer">附录2《常见食物交换表》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=19" target="_blank" rel="noreferrer">附录3《不同地区食谱示例》</a></strong>（西北、华北等地区分季节食谱）· <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=31" target="_blank" rel="noreferrer">附录4《食养方举例》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/growth-retardation-2023.pdf#page=33" target="_blank" rel="noreferrer">附录5《判定标准》</a></strong>。</li><li>食养方用法用量示例（如餐前 30～60 分钟喝 1 小碗汤、每周 2～3 次），详见原文附录。</li></ul><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2023 年版（现行）</td></tr><tr><td>印发时间</td><td>2023 年 1 月</td></tr><tr><td>原文直链</td><td><a href="https://www.nhc.gov.cn/sps/c100088/202301/f01895a06c5349ef999f25da833c166d/files/1732844467736_68919.pdf" target="_blank" rel="noreferrer">卫健委官网 PDF</a> · <a href="https://www.chinacdc.cn/jkyj/yyyjk2/jswj13949/202504/t20250407_305776.html" target="_blank" rel="noreferrer">疾控中心全文页</a></td></tr></tbody></table>',20)])])}const u=r(o,[["render",h]]);export{p as __pageData,u as default};
